/** Host lifetime achievement counters, combat and objective rules. Disk acknowledgments precede announcements. */
public final class HostedAchievements {
    public record Identity(String legacyId,String steamId){public Identity{if(legacyId!=null&&!legacyId.matches("[0-9]{1,128}")||steamId!=null&&!steamId.matches("steam:[0-9]{17}"))throw new IllegalArgumentException("Achievement identity must be independently verified");}}
    public record Prepared(AchievementStore store,Map<String,AchievementStore.Account> snapshot,ExecutorService worker) implements AutoCloseable {public Prepared{snapshot=Map.copyOf(snapshot);}@Override public void close(){worker.shutdownNow();}}
    /** Null path explicitly selects memory; durable Java state uses its own file, never a legacy SQLite filename. */
    public static CompletionStage<Prepared> prepare(Path path){var worker=Executors.newSingleThreadExecutor(Thread.ofPlatform().daemon().name("achievement-store").factory());var future=CompletableFuture.supplyAsync(()->{try{var store=new AchievementStore(path);return new Prepared(store,store.snapshot(),worker);}catch(java.io.IOException failure){throw new CompletionException(failure);}},worker);future.whenComplete((value,error)->{if(error!=null)worker.shutdown();});return future;}
    private static final class Tracker {String identity;boolean resolved;final Map<String,Double> fractions=new HashMap<>(),match=new HashMap<>(),round=new HashMap<>();Vector last;int sniper;final ArrayDeque<Double> rapid=new ArrayDeque<>();PlayerLife lastSource;int lastType=-1;boolean lastBelow;}
    private final AchievementEnvironment environment=new AchievementEnvironment(this);
    public record CrateBaseline(int health,int weapon,int reserve){}
    public final class BlastScope implements AutoCloseable {private final AchievementEnvironment.Blast scope;private BlastScope(AchievementEnvironment.Blast scope){this.scope=scope;}@Override public void close(){guard("blast_end",()->environment.end(scope));}}
    public BlastScope blastBegin(StandardMatchDomain match,PlayerLife thrower,int type,Vector origin){owned();return new BlastScope(environment.begin(match,thrower,type,origin));}
    public void projectileExploding(StandardMatchDomain match,net.battlespades.entities.ProjectileEngine.Projectile projectile,PlayerLife thrower){owned();environment.projectile(match,projectile,thrower);}
    public void blocksDestroyed(StandardMatchDomain match,PlayerLife player,List<net.battlespades.world.BlockDamageModel.Cell> removed,List<net.battlespades.world.BlockDamageModel.Cell> collapsed,List<List<net.battlespades.world.BlockDamageModel.Cell>> chunks,Integer tool){owned();environment.blocks(match,player,removed,collapsed,chunks,tool);}
    public CrateBaseline crateBaseline(PlayerLife p){owned();return new CrateBaseline(p.health(),p.inventory().weapon(),p.inventory().ammo().reserve());}
    public void crateCollected(StandardMatchDomain match,PlayerLife p,int award,CrateBaseline before){owned();environment.crate(match,p,award,before);}
    boolean zombie(PlayerLife p){return zombieRound&&p.team()==2;}boolean counting(){return roundOpen;}boolean countBotKills(){return countBotKills;}
    private record Key(String identity,String stat){}
    private static final class ObjectiveTrack {PlayerLife hotfoot,thief,interceptor;}
    private static final class Strike {final ObjectiveZone zone;final Set<PlayerLife> survivors=Collections.newSetFromMap(new IdentityHashMap<>()),stayed=Collections.newSetFromMap(new IdentityHashMap<>());double elapsed;Strike(ObjectiveZone zone){this.zone=zone;}}
    private final Map<Integer,ObjectiveTrack> diamonds=new HashMap<>(),bombs=new HashMap<>();
    private final Map<Integer,PlayerLife> intelInterceptors=new HashMap<>();private final Map<Integer,Set<PlayerLife>> hillScorers=new HashMap<>();private final List<Strike> strikes=new ArrayList<>();
    private List<PlayerLife> initialZombies=List.of();private Map<Integer,PlayerLife> vips;private PlayerLife lastBombPlanter;
    private boolean connected(StandardMatchDomain m,PlayerLife p){return p!=null&&m.lives().players().stream().anyMatch(v->v==p);}
    boolean live(StandardMatchDomain m){return roundOpen&&!m.mode().clock().ended&&!m.mode().clock().retiring;}
    double count(PlayerLife p,boolean round,String key,double amount){var values=round?tracker(p).round:tracker(p).match;return values.merge(key,amount,Double::sum);}

    private final Thread owner=Thread.currentThread();private final ApplicationHost host;private final Prepared prepared;private final Function<JoinSession,Optional<Identity>> verified;private final LifeRuntime.Clock clock;private final OwnerLoop resume;private final boolean countBotKills;
    private final Map<JoinSession,Tracker> connectionTrackers=new IdentityHashMap<>();private final Map<PlayerLife,Tracker> trackers=new IdentityHashMap<>();private final Map<String,AchievementStore.Account> accounts=new HashMap<>();private final Map<Key,Long> dirty=new LinkedHashMap<>(),persisting=new LinkedHashMap<>();private final Map<String,String> names=new HashMap<>();private final Map<String,AchievementStore.Request> requests=new LinkedHashMap<>();
    private Map<String,AchievementStore.Request> persistingRequests=Map.of();
    private final Map<String,Long> faults=new LinkedHashMap<>();private CompletableFuture<Void> shutdown;private CompletionStage<Void> inFlight;private double flushIn=10,retryAt;private boolean roundOpen=true,closing,stopped,zombieRound;
    public HostedAchievements(ApplicationHost host,Prepared prepared,Function<JoinSession,Optional<Identity>> verified,LifeRuntime.Clock clock,OwnerLoop resume,boolean countBotKills){this.host=Objects.requireNonNull(host);this.prepared=Objects.requireNonNull(prepared);this.verified=Objects.requireNonNull(verified);this.clock=Objects.requireNonNull(clock);this.resume=Objects.requireNonNull(resume);this.countBotKills=countBotKills;accounts.putAll(prepared.snapshot);host.achievements(this);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Achievements outside owner");}
    private Tracker tracker(PlayerLife p){return trackers.computeIfAbsent(p,key->{var session=host.transitionSessions().stream().filter(v->v.playerId().orElse(-1)==p.id()).findFirst().orElse(null);return session==null?new Tracker():connectionTrackers.computeIfAbsent(session,k->new Tracker());});}
    public String identity(PlayerLife p){owned();if(p==null||p.bot())return null;var t=tracker(p);if(t.resolved)return t.identity;var session=host.transitionSessions().stream().filter(s->s.playerId().orElse(-1)==p.id()).findFirst();var id=session.flatMap(verified).orElse(null);t.identity=id!=null&&id.legacyId!=null?"aosplay:"+id.legacyId:id!=null&&id.steamId!=null?id.steamId:NameUnicode.strip(p.name()).isEmpty()?null:"name:"+NameUnicode.casefold(NameUnicode.strip(p.name()));t.resolved=true;return t.identity;}
    private void fault(String label,Throwable failure){long n=faults.merge(label,1L,Long::sum);if(n==1)System.getLogger("achievements").log(System.Logger.Level.WARNING,"Achievement hook "+label+" failed",failure);}
    public Map<String,Long> faults(){owned();return Map.copyOf(faults);}
    public void guard(String label,Runnable action){owned();if(closing)return;try{action.run();}catch(RuntimeException failure){fault(label,failure);}}
    public <T>T guard(String label,Supplier<T> action,T fallback){owned();if(closing)return fallback;try{return action.get();}catch(RuntimeException failure){fault(label,failure);return fallback;}}
    public Map<String,Long> progress(String identity){owned();var out=new LinkedHashMap<>(accounts.getOrDefault(identity,new AchievementStore.Account(Map.of(),Map.of())).counters());for(var values:List.of(dirty,persisting))values.forEach((key,value)->{if(key.identity.equals(identity))out.merge(key.stat,value,Math::addExact);});return Map.copyOf(out);}
    public Map<String,AchievementStore.Unlock> unlocked(String identity){owned();return accounts.getOrDefault(identity,new AchievementStore.Account(Map.of(),Map.of())).unlocks();}
    public void add(PlayerLife p,String stat,long amount){owned();if(!AchievementCatalog.tiers().containsKey(stat))throw new IllegalArgumentException("Unknown achievement statistic");String id=identity(p);if(closing||id==null||amount<=0)return;names.put(id,p.name());dirty.merge(new Key(id,stat),amount,Math::addExact);long value=progress(id).getOrDefault(stat,0L);if(AchievementCatalog.tiers().get(stat).stream().anyMatch(t->value>=t.threshold()&&!unlocked(id).containsKey(t.apiName())))flush();}
    public void fraction(PlayerLife p,String stat,double amount){owned();if(!Double.isFinite(amount)||amount<0)throw new IllegalArgumentException("Invalid achievement fraction");var t=tracker(p);double value=t.fractions.getOrDefault(stat,0.)+amount;long whole=(long)(value+1e-9);t.fractions.put(stat,Math.max(0,value-whole));if(whole>0)add(p,stat,whole);}
    public void unlock(PlayerLife p,String api){owned();if(!AchievementCatalog.definitions().containsKey(api))throw new IllegalArgumentException("Unknown achievement");String id=identity(p);if(closing||id==null||unlocked(id).containsKey(api))return;names.put(id,p.name());requests.putIfAbsent(id+'\0'+api,new AchievementStore.Request(id,api,p.name()));flush();}
    /** One immutable transaction at a time; failed deltas are restored exactly once for a later retry. */
    public CompletionStage<Void> flush(){owned();if(stopped)return CompletableFuture.completedFuture(null);if(inFlight!=null)return inFlight;if(dirty.isEmpty()&&requests.isEmpty())return CompletableFuture.completedFuture(null);if(!closing&&clock.monotonic()<retryAt)return CompletableFuture.completedFuture(null);
        var deltas=new LinkedHashMap<>(dirty);persisting.putAll(deltas);dirty.clear();var pending=new LinkedHashMap<>(requests);persistingRequests=pending;requests.clear();var rows=deltas.entrySet().stream().map(e->new AchievementStore.Delta(e.getKey().identity,e.getKey().stat,e.getValue(),names.getOrDefault(e.getKey().identity,"Player"))).toList();var result=new CompletableFuture<Void>();inFlight=result.minimalCompletionStage();double now=clock.wall();
        CompletableFuture.supplyAsync(()->{try{return prepared.store.transact(rows,List.copyOf(pending.values()),Set.of(),now);}catch(java.io.IOException failure){throw new CompletionException(failure);}},prepared.worker).whenCompleteAsync((receipt,error)->{
            inFlight=null;persisting.clear();persistingRequests=Map.of();if(error!=null){deltas.forEach((key,value)->dirty.merge(key,value,Math::addExact));pending.forEach(requests::putIfAbsent);retryAt=clock.monotonic()+5;fault("persist",error);result.completeExceptionally(error);return;}accounts.clear();accounts.putAll(receipt.accounts());retryAt=0;for(var created:receipt.created())try{host.broadcast(Announcements.localised("ACHIEVEMENT_GAINED",List.of(created.playerName(),AchievementCatalog.definitions().get(created.apiName()).displayName()),true,false),Delivery.RELIABLE);}catch(RuntimeException failed){fault("announce",failed);}result.complete(null);
            if(!closing&&(!requests.isEmpty()||dirty.keySet().stream().anyMatch(key->AchievementCatalog.tiers().get(key.stat).stream().anyMatch(tier->progress(key.identity).getOrDefault(key.stat,0L)>=tier.threshold()&&!unlocked(key.identity).containsKey(tier.apiName())))))flush();
        },resume);return result.minimalCompletionStage();
    }
    /** Immutable eligibility at result capture, including counter tiers and unacknowledged one-shot requests. */
    public Set<String> eligible(String id){owned();var result=new HashSet<>(unlocked(id).keySet());var counters=progress(id);AchievementCatalog.tiers().forEach((stat,tiers)->{for(var tier:tiers)if(counters.getOrDefault(stat,0L)>=tier.threshold())result.add(tier.apiName());});for(var pending:List.of(requests,persistingRequests))for(var request:pending.values())if(request.identity().equals(id))result.add(request.apiName());return Set.copyOf(result);}
    /** Durable ordered handoff, limited to unlocks earned by the caller's capture boundary. */
    public CompletionStage<List<String>> takeUnreported(String id){owned();return takeUnreported(id,eligible(id));}
    public CompletionStage<List<String>> takeUnreported(String id,Set<String> eligibility){owned();if(closing)return CompletableFuture.failedFuture(new IllegalStateException("Achievements are closing"));var eligible=Set.copyOf(eligibility);double at=clock.wall();return flushFully().thenCompose(unused->CompletableFuture.supplyAsync(()->{try{return prepared.store.takeSelected(id,eligible,at);}catch(java.io.IOException failure){throw new CompletionException(failure);}},prepared.worker)).thenApplyAsync(receipt->{accounts.clear();accounts.putAll(receipt.accounts());return receipt.taken().getOrDefault(id,List.of());},resume);}
    private CompletionStage<Void> flushFully(){owned();retryAt=0;return flush().thenComposeAsync(unused->dirty.isEmpty()&&requests.isEmpty()?CompletableFuture.completedFuture(null):flushFully(),resume);}
    public void depart(PlayerLife p,boolean transition){owned();var t=trackers.remove(p);if(t!=null){t.last=null;t.lastSource=null;if(!transition)connectionTrackers.values().removeIf(current->current==t);}flushFully();}
    public void round(boolean started){owned();roundOpen=started;if(started)trackers.values().forEach(t->t.round.clear());}
    public void matchStarted(StandardMatchDomain match){matchStarted();environment.start(match);}
    public void matchStarted(){owned();environment.reset();roundOpen=true;zombieRound=false;diamonds.clear();bombs.clear();intelInterceptors.clear();hillScorers.clear();strikes.clear();initialZombies=List.of();vips=null;lastBombPlanter=null;var all=Collections.newSetFromMap(new IdentityHashMap<Tracker,Boolean>());all.addAll(trackers.values());all.addAll(connectionTrackers.values());for(var t:all){t.match.clear();t.round.clear();t.sniper=0;t.rapid.clear();t.lastSource=null;}}
    public void matchEnded(StandardMatchDomain match,Integer winner){owned();if(vips!=null)vipRound(match,match.vip().map(HostedVipRuntime::roundObservation).orElse(new HostedVipRuntime.RoundObservation(false,Map.of(),Set.of())));environment.ended(match,winner);if(roundOpen&&winner!=null&&connected(match,lastBombPlanter)&&lastBombPlanter.team()==winner)unlock(lastBombPlanter,"bomb_final_bomber");roundOpen=false;strikes.clear();flushFully();}
    private static int c(String name){return AchievementCatalog.constant(name);}
    private static boolean is(int value,String... constants){for(var constant:constants)if(value==c(constant))return true;return false;}
    public void damaged(LifeRuntime.DamageEvidence event){owned();if(event.source()!=null&&event.source()!=event.victim()&&event.removed()>0){var t=tracker(event.victim());t.lastSource=event.source();t.lastType=event.killType();t.lastBelow=environment.damaged(event);}}
    public void resolved(ShotTally.Resolved event){owned();if(!event.hit()&&event.tool()==c("SNIPER_TOOL"))tracker(event.player()).sniper=0;}
    public void died(StandardMatchDomain match,LifeRuntime.DeathEvidence event){owned();var victim=event.victim();var old=tracker(victim);var last=old.lastSource;int lastType=old.lastType;boolean below=old.lastBelow;old.lastSource=null;old.lastBelow=false;var killer=event.killer();int type=event.presentationType();if(!roundOpen||match.mode().clock().ended||match.mode().clock().retiring||is(type,"FORCED_TEAM_CHANGE_KILL","TEAM_CHANGE_KILL","CLASS_CHANGE_KILL")||killer==null||killer==victim||killer.team()==victim.team()||!Set.of(2,3).contains(killer.team())||!Set.of(2,3).contains(victim.team()))return;
        count(killer,true,"kills",1);if(killer.bot()||victim.bot()&&!countBotKills)return;count(killer,true,"counted_kills",1);
        int tool=killer.inventory().tool();boolean gun=is(type,"WEAPON_KILL","HEADSHOT_KILL"),head=type==c("HEADSHOT_KILL"),melee=type==c("MELEE_KILL");boolean zombie=zombieRound;boolean kz=zombie&&killer.team()==2,vz=zombie&&victim.team()==2;long streak=match.binding().row(killer).killStreak;var t=tracker(killer);
        if(streak==5||streak==10||streak==15)unlock(killer,streak==5?"misc_five_in_a_row":streak==10?"misc_ten_in_a_row":"misc_fifteen_in_a_row");
        if(melee){if(is(tool,"SPADE_TOOL","CLASSIC_SPADE_TOOL"))add(killer,"spade_kill_count",1);else if(tool==c("PICKAXE_TOOL"))add(killer,"pickaxe_kill_count",1);else if(tool==c("KNIFE_TOOL")&&vz)add(killer,"knife_zombie_count",1);}
        if(head){if(tool==c("SNIPER_TOOL"))add(killer,"sniper_kill_count",1);else if(tool==c("SHOTGUN_TOOL"))add(killer,"shotgun_headshots_count",1);else if(tool==c("RIFLE_TOOL"))add(killer,"classic_rifle_headshot_count",1);else if(is(tool,"PISTOL_TOOL","SNUB_PISTOL_TOOL")&&vz)add(killer,"pistol_zombie_kill_count",1);}
        if(gun&&tool==c("SNIPER_TOOL")){t.sniper++;if(t.sniper==3||t.sniper==6)unlock(killer,t.sniper==3?"sniper_accuracy":"sniper_accuracy_hard");}
        if(gun&&tool==c("SNIPER2_TOOL")){double now=clock.monotonic();t.rapid.addLast(now);while(!t.rapid.isEmpty()&&now-t.rapid.getFirst()>AchievementCatalog.number("SNIPER2_RAPID_KILL_ACHIEVE_TIME"))t.rapid.removeFirst();if(t.rapid.size()>=c("SNIPER2_RAPID_KILL_ACHIEVE_COUNT"))unlock(killer,"sniper2_rapid_kill");}
        if(killer.flight().snapshot().active()){add(killer,"jetpack_kill_count",1);if(gun&&tool==c("SMG_TOOL"))add(killer,"jetpack_smg_kill_count",1);}if(victim.diedJetpacking())unlock(killer,"jetpack_killed_using");if(killer.alive()&&killer.health()>0&&killer.health()<killer.maxHealth()*.1)add(killer,"low_health_kills",1);
        if(type==c("FALL_KILL")){if(kz)unlock(killer,"zombie_fall");if(last==killer&&is(lastType,"ROCKET_KILL","ROCKET2_KILL"))unlock(killer,"rocket_fall");}
        environment.killed(match,killer,victim,type,below,last,lastType);
        if(kz&&count(killer,true,"zombie_kills",1)==3)unlock(killer,"zombie_kills_humans");if(vz&&match.zombie().flatMap(HostedZombieRuntime::lastSurvivor).orElse(null)==killer){double kills=count(killer,true,"last_man_kills",1);if(kills==5||kills==10)unlock(killer,kills==5?"lastman_kills_zombies_easy":"lastman_kills_zombies_hard");}
        if(kz&&killer.body().state().wade())add(killer,"zombie_kills_in_water",1);if(match.modeCode().equals("cctf")&&killer.pickupId()!=null)add(killer,"classic_kills_with_intel_count",1);
    }
    public void tick(StandardMatchDomain match,double dt){owned();if(closing||!(dt>0&&dt<=1))return;if(roundOpen&&!match.mode().clock().ended&&!match.mode().clock().retiring)for(var p:match.lives().players()){if(p.bot())continue;var t=tracker(p);var at=p.position();var previous=t.last;t.last=at;if(!p.alive()||!Set.of(2,3).contains(p.team()))continue;if(match.zombie().flatMap(HostedZombieRuntime::lastSurvivor).orElse(null)==p){fraction(p,"zombie_seconds_as_lms_count",dt);if(count(p,true,"last_man_seconds",dt)>=28)unlock(p,"zombie_lms_one_round");}if(p.body().state().airborne())fraction(p,"airborne_seconds_count",dt);else if(previous!=null){double distance=net.battlespades.combat.CombatGeometry.distance(previous,at);if(distance>0&&distance<=2)fraction(p,"distance_run",distance);}}
        if(live(match))tickStrikes(match,dt);environment.tick(match,dt);
        flushIn-=dt;if(flushIn<=0){flushIn=10;flush();}else if(retryAt>0&&clock.monotonic()>=retryAt)flush();
    }
    private void mostKills(StandardMatchDomain match,Collection<PlayerLife> candidates,String api){for(var p:candidates){if(!connected(match,p))continue;double own=tracker(p).round.getOrDefault("counted_kills",0.);if(own>=1&&match.lives().players().stream().filter(v->v!=p).allMatch(v->tracker(v).round.getOrDefault("kills",0.)<=own))unlock(p,api);}}
    public void zombieRound(StandardMatchDomain match,HostedZombieRuntime.RoundObservation event){owned();if(event.started()){zombieRound=true;initialZombies=event.players();round(true);}else{if(live(match)){for(var p:event.players())if(p.alive())unlock(p,"zombie_survivor");mostKills(match,initialZombies,"zombie_mvp");}initialZombies=List.of();roundOpen=false;}}
    public void vipRound(StandardMatchDomain match,HostedVipRuntime.RoundObservation event){owned();if(event.started()){vips=event.vips();round(true);return;}var old=vips;vips=null;if(old!=null&&roundOpen){mostKills(match,old.values(),"vip_mvp");for(var entry:old.entrySet()){var p=entry.getValue();if(event.vips().get(entry.getKey())==p&&event.alive().contains(entry.getKey())&&p.alive()&&tracker(p).round.getOrDefault("kills",0.)==0)unlock(p,"vip_pacifist");}}roundOpen=false;}
    public void carry(StandardMatchDomain match,HostedCarryRuntime.Observation event){owned();var p=event.player();int serial=event.serial();switch(event.event()){
        case "diamond_picked_up"->{var t=diamonds.computeIfAbsent(serial,k->new ObjectiveTrack());t.hotfoot=t.interceptor=null;if(event.seconds()!=null){if(event.seconds()<=5)t.hotfoot=p;var finder=event.other();if(finder!=null&&finder!=p&&Set.of(2,3).contains(finder.team())&&finder.team()!=p.team())t.thief=p;}else if(Set.of(2,3).contains(event.team())&&event.team()!=p.team())t.interceptor=p;}
        case "diamond_cashed_in"->{var t=diamonds.remove(serial);if(!live(match))break;if(t!=null){if(t.hotfoot==p)unlock(p,"diamond_hotfoot");if(t.thief==p)add(p,"diamond_thief_count",1);if(t.interceptor==p)add(p,"diamond_interceptor_count",1);}if(event.flag()&&count(p,false,"diamonds_found",1)==3)unlock(p,"diamond_collector");}
        case "bomb_picked_up"->{var t=bombs.computeIfAbsent(serial,k->new ObjectiveTrack());t.hotfoot=event.flag()&&p.team()==2?p:null;if(p.team()==2)t.interceptor=null;}
        case "bomb_dropped"->{var t=bombs.get(serial);if(t!=null){boolean carried=t.hotfoot==p&&event.flag();t.hotfoot=null;if(carried&&live(match))unlock(p,"bomb_hotfoot");}}
        case "bomb_carrier_killed"->{if(live(match)&&(!event.other().bot()||countBotKills))bombs.computeIfAbsent(serial,k->new ObjectiveTrack()).interceptor=p;}
        case "bomb_detonated"->{var t=bombs.remove(serial);if(!live(match))break;if(event.flag()){if(p!=null){lastBombPlanter=p;if(p.alive())unlock(p,"bomb_survivor");}}else if(t!=null&&connected(match,t.interceptor))add(t.interceptor,"bomb_interceptor_count",1);}
        default->throw new IllegalArgumentException("Unknown achievement carry observation: "+event.event());
    }}
    public void intelPickedUp(int team){owned();intelInterceptors.remove(team);}
    public void intelCarrierKilled(StandardMatchDomain match,PlayerLife killer,PlayerLife victim,int team,int type){owned();intelInterceptors.remove(team);if(live(match)&&killer!=null&&killer!=victim&&!is(type,"FORCED_TEAM_CHANGE_KILL","TEAM_CHANGE_KILL","CLASS_CHANGE_KILL")&&killer.team()==team&&victim.team()!=team&&(!victim.bot()||countBotKills))intelInterceptors.put(team,killer);}
    public void intelReturned(StandardMatchDomain match,int team){owned();var p=intelInterceptors.remove(team);if(live(match)&&connected(match,p)&&p.team()==team)add(p,"intel_defence_count",1);}
    public void hill(StandardMatchDomain match,HostedZoneRuntime.HillEvent event){owned();switch(event){
        case HostedZoneRuntime.Scored e->hillScorers.computeIfAbsent(e.zone().index(),k->Collections.newSetFromMap(new IdentityHashMap<>())).add(e.player());
        case HostedZoneRuntime.ContestWon e->{if(live(match))for(var p:e.players())add(p,e.retained()?"hill_defender_count":"hill_interceptor_count",1);}
        case HostedZoneRuntime.HillKill e->{if(live(match)&&(!e.victim().bot()||countBotKills)){if(e.killerInside())add(e.killer(),"hill_kill_shooting_out_count",1);if(e.victimInside())add(e.killer(),"hill_kill_shooting_in_count",1);}}
        case HostedZoneRuntime.Expired e->{var scorers=hillScorers.remove(e.zone().index());if(!live(match))break;if(scorers!=null&&scorers.size()==1){var only=scorers.iterator().next();if(connected(match,only))unlock(only,"hill_greedy");}var strike=new Strike(e.zone());for(var entry:e.occupants().entrySet()){var p=entry.getValue();if(!p.bot()&&p.alive()&&Objects.equals(e.teams().get(entry.getKey()),p.team())){strike.survivors.add(p);strike.stayed.add(p);}}if(!strike.survivors.isEmpty())strikes.add(strike);}
    }}
    private void tickStrikes(StandardMatchDomain match,double dt){boolean flight=match.entities().projectiles().engine().projectiles().stream().anyMatch(p->p.spec==net.battlespades.entities.ProjectileSpec.AIRSTRIKE);for(var iterator=strikes.iterator();iterator.hasNext();){var strike=iterator.next();strike.elapsed+=dt;for(var it=strike.survivors.iterator();it.hasNext();){var p=it.next();if(!connected(match,p)||!p.alive()){it.remove();strike.stayed.remove(p);}else if(!strike.zone.contains(p.position()))strike.stayed.remove(p);}if(strike.elapsed<1||flight&&strike.elapsed<15)continue;iterator.remove();for(var p:strike.survivors){add(p,"hill_strike_survivor_count",1);if(strike.stayed.contains(p))unlock(p,"hill_strike_stay_put");}}}
    public CompletionStage<Void> shutdown(){owned();if(shutdown!=null&&!shutdown.isCompletedExceptionally())return shutdown.minimalCompletionStage();closing=true;shutdown=flushFully().thenComposeAsync(unused->CompletableFuture.runAsync(()->{},prepared.worker),resume).thenRunAsync(()->{stopped=true;prepared.worker.shutdown();environment.reset();trackers.clear();connectionTrackers.clear();},resume).toCompletableFuture();return shutdown.minimalCompletionStage();}
    boolean stopped(){owned();return stopped;}
}
